  "Scarcity": {"Explanation": "Not present. The email does not mention limited time, quantity, or opportunity to act, nor does it create urgency around a time-sensitive offer."},
  "Authority": {"Explanation": "Not present. While the sender claims a connection to a former African leader, the claim is fabricated and lacks credible verification or institutional endorsement. There is no recognized authority, title, or legitimate institution cited to establish credibility."},
  "Commitment/Consistency": {"Explanation": "Not present. The email does not reference prior actions, decisions, or behaviors of the recipient to encourage continued compliance or alignment."},
  "Liking": {"Explanation": "Not present. The email does not use personalization, flattery, or familiarity to build rapport or trust. The tone is formal, urgent, and suspicious rather than warm or relatable."},
  "Social proof": {"Explanation": "Not present. The email does not reference the actions or opinions of others to suggest that the proposed action is popular or endorsed by peers or groups."}
}

